mapper.select:
select version_id, list_type, item_id, content_hash, volatile_data
from ${tableName}
where list_type = #{listType} and content_hash in
#{hash}

select version_id, list_type, item_id, payload, volatile_data
from ${tableName}
where version_id in
#{id}

mapper.update:
update ${tableName} set last_sync_id = #{syncId}
where version_id in
#{id}

update ${tableName}
set volatile_data = case version_id
    when #{it.versionId} then #{it.volatileData} 
end,
update_time = sysdate()
where version_id in
#{it.versionId}

mapper.select:
select version_id, list_type, item_id, content_hash, symbol, signal_id, item_state, item_kind, item_date,
       volatile_data, first_sync_id, last_sync_id, create_time, update_time
from ${tableName}

    and list_type = #{item.listType}
    and item_id = #{item.itemId}
    and symbol = #{item.symbol}
    and signal_id = #{item.signalId}
    and item_state = #{item.itemState}
    and item_kind = #{item.itemKind}

order by version_id desc
